UPDATE campus_event
event_title = #{eventTitle}, event_type = #{eventType}, event_summary = #{eventSummary}, first_publish_time = #{firstPublishTime}, discover_time = #{discoverTime}, risk_level = #{riskLevel}, impact_scope = #{impactScope}, involved_department_id = #{involvedDepartmentId}, current_heat = #{currentHeat}, event_status = #{eventStatus}, disposal_requirement = #{disposalRequirement}, update_user_id = #{updateUserId}
WHERE event_id = #{eventId} AND deleted = 0

UPDATE campus_event
SET event_status = #{eventStatus},
    update_user_id = #{updateUserId}
WHERE event_id = #{eventId}
  AND deleted = 0

UPDATE campus_event
SET archive_conclusion = #{archiveConclusion},
    event_status = 'archived',
    update_user_id = #{updateUserId}
WHERE event_id = #{eventId}
  AND deleted = 0

mapper.select:
SELECT 
FROM campus_event
WHERE deleted = 0

    AND (event_title LIKE CONCAT('%', #{keyword}, '%') OR event_summary LIKE CONCAT('%', #{keyword}, '%'))


    AND risk_level = #{riskLevel}


    AND event_status = #{eventStatus}


    AND discover_time >= #{startTime}


    AND discover_time <= #{endTime}

ORDER BY update_time DESC, id DESC
